/* --- 示意圖框 --- */
function iconBox(x, y, w, h, a) {
  ctx.save(); ctx.globalAlpha *= a;
  ctx.fillStyle = "rgba(18,24,30,.55)";
  ctx.strokeStyle = "rgba(93,127,163,.30)"; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.roundRect(x, y, w, h, 8); ctx.fill(); ctx.stroke();
  ctx.restore();
}

/* --- 痛點示意圖 --- */
function painIcon(i, x, y, w, h, t, a) {
  iconBox(x, y, w, h, a);
  ctx.save(); ctx.globalAlpha *= a;
  const cx = x + w / 2;
  if (i === 0) {
    const n = Math.floor(clamp(t / 1.4, 0, 1) * 11);
    for (let k = 0; k < n; k++) {
      const off = Math.sin(t * 3 + k) * 1.5;
      ctx.fillStyle = k > 8 ? "rgba(224,90,79,.55)" : "rgba(143,154,165,.35)";
      ctx.fillRect(cx - 70 + off, y + h - 24 - k * 11, 140, 8);
    }
  } else if (i === 1) {
    ctx.fillStyle = "rgba(143,154,165,.22)"; ctx.fillRect(cx - 62, y + 28, 44, 96);
    const e = eOut(clamp(t / 1.2, 0, 1));
    ctx.fillStyle = "rgba(241,178,92,.85)";
    ctx.fillRect(cx + 6, y + 124 - 44 * e, 44, 44 * e);
    ctx.fillStyle = "rgba(232,236,239,.9)"; ctx.font = "34px " + F.mono; ctx.fillText("?", cx - 12, y + 82);
  } else if (i === 2) {
    for (let k = 0; k < 3; k++) {
      const ccx = cx - 62 + k * 62, ccy = y + 66, R = 24;
      ctx.strokeStyle = "rgba(143,154,165,.45)"; ctx.lineWidth = 1.5;
      ctx.beginPath(); ctx.arc(ccx, ccy, R, 0, TAU); ctx.stroke();
      const ang = -Math.PI / 2 + Math.sin(t * 1.6 + k) * 1.9;
      ctx.strokeStyle = "rgba(241,178,92,.8)";
      ctx.beginPath(); ctx.moveTo(ccx, ccy); ctx.lineTo(ccx + Math.cos(ang) * R * .8, ccy + Math.sin(ang) * R * .8); ctx.stroke();
    }
  } else {
    for (let k = 0; k < 6; k++) {
      const yy = y + 26 + k * 18;
      const leak = k === 1 || k === 4;
      ctx.strokeStyle = leak ? "rgba(224,90,79,.75)" : "rgba(143,154,165,.30)";
      ctx.lineWidth = 2; ctx.setLineDash(leak ? [5, 5] : []);
      ctx.beginPath();
      ctx.moveTo(x + 26 + (leak ? 26 : 0), yy);
      ctx.lineTo(x + w - 26 + (leak ? 34 : 0), yy);
      ctx.stroke();
    }
    ctx.setLineDash([]);
  }
  ctx.restore();
}

/* --- 解法示意圖 --- */
function ansIcon(i, x, y, w, h, t, a) {
  iconBox(x, y, w, h, a);
  ctx.save(); ctx.globalAlpha *= a;
  const cx = x + w / 2;
  const e = eOut(clamp(t / 1.2, 0, 1));
  if (i === 0) {
    ctx.strokeStyle = "rgba(241,178,92,.5)"; ctx.lineWidth = 1.5;
    for (let k = 0; k < 4; k++) {
      ctx.beginPath();
      ctx.moveTo(x + 26, y + 18 + k * 30);
      ctx.lineTo(cx - 20, y + h / 2 - 14 + k * 9);
      ctx.stroke();
    }
    for (let k = 0; k < 4; k++) {
      ctx.fillStyle = "rgba(241,178,92," + (0.35 + 0.15 * k) * e + ")";
      ctx.fillRect(cx + 4, y + 22 + k * 27, (w / 2 - 26) * e, 8);
    }
  } else if (i === 1) {
    const r = rng(31);
    for (let k = 0; k < 26; k++) {
      ctx.fillStyle = "rgba(143,154,165,.35)";
      ctx.beginPath(); ctx.arc(x + 30 + r() * (w - 60), y + 40 + r() * 60, 2.6, 0, TAU); ctx.fill();
    }
    for (let k = 0; k < 8; k++) {
      ctx.fillStyle = "rgba(241,178,92,.9)";
      ctx.beginPath();
      ctx.arc(x + 40 + k * 12, y + h - 26 - e * (k * 5 + 8), 3.4, 0, TAU);
      ctx.fill();
    }
  } else if (i === 2) {
    for (let k = 0; k < 3; k++) {
      const ccx = cx - 54 + k * 54, ccy = y + h / 2, R = 20;
      ctx.strokeStyle = "rgba(241,178,92," + (0.35 + 0.4 * e) + ")"; ctx.lineWidth = 2;
      ctx.beginPath(); ctx.arc(ccx, ccy, R, 0, TAU * e); ctx.stroke();
    }
  } else {
    for (let k = 0; k < 4; k++) {
      ctx.fillStyle = "rgba(241,178,92," + (0.25 + 0.5 * e) + ")";
      ctx.fillRect(x + 26, y + 22 + k * 26, (w - 52) * e, 10);
    }
  }
  ctx.restore();
}

/* --- 0–7s：粒子聚成地球，再爆散成紅點 --- */
function sceneMap(t) {
  const a = 1 - ss(6.4, 6.95, t);
  if (a <= 0) return;
  ctx.save(); ctx.globalAlpha = a;
  const form = eOut(clamp(t / 2.6, 0, 1));
  const burst = ss(3.2, 6.4, t);
  const rot = t * 0.5;
  ctx.globalCompositeOperation = "lighter";
  PT.forEach(p => {
    const th = p.th + rot;
    const gx = 960 + Math.cos(th) * Math.sin(p.ph) * 300 * (0.6 + 0.4 * ((Math.sin(th) * Math.sin(p.ph) + 1) / 2));
    const gy = 500 + Math.cos(p.ph) * 300;
    let x = lerp(p.sx, gx, form), y = lerp(p.sy, gy, form);
    if (burst > 0) { x += Math.cos(p.th * 3) * burst * 260 * (0.4 + p.jx); y -= burst * 220 * (0.3 + p.jy); }
    ctx.fillStyle = burst > 0.12 ? "rgba(224,90,79," + (0.22 + 0.5 * burst) + ")" : "rgba(120,160,200,.34)";
    ctx.fillRect(x, y, p.sz, p.sz);
  });
  ctx.globalCompositeOperation = "source-over";
  text("全球資安通報，沒有一刻停下來", 150, 150, { size: 42, weight: 600 });
  text("SCHEMATIC · 示意動畫，非實際統計", 150, 196, { size: 21, color: C.dim, font: F.mono, space: 2 });
  const ea = ss(4.4, 5.2, t);
  if (ea > 0) {
    const items = [[DATA.total + " 篇", "情資語料"], [DATA.dedup + " 個", "去重後事件"], [DATA.months.n + " 個月", "連續涵蓋"]];
    items.forEach((it, i) => {
      const x = 150 + i * 320;
      text(it[0], x, 900, { size: 42, color: i === 0 ? C.hi : C.ink, font: F.mono, weight: 600, alpha: ea });
      text(it[1], x, 940, { size: 20, color: C.mute, alpha: ea });
    });
    text("紅點為示意，不代表任何國家的實際受害數", 1620, 902, { size: 18, color: C.dim, align: "right", alpha: ea });
  }
  ctx.restore();
}

/* --- 7–14.5s：粒子堆成四座塔，每座塔上方一張示意圖 --- */
function scenePains(t) {
  const a = ss(-0.45, 0.05, t) * (1 - ss(7.0, 7.5, t));
  if (a <= 0) return;
  ctx.save(); ctx.globalAlpha = a;
  ctx.globalCompositeOperation = "lighter";
  PT.forEach(p => {
    const grow = eOut(clamp((t - 0.15 - p.row * 0.3) / 1.5, 0, 1));
    const bx = TOWERX[p.row];
    const h = (150 + p.row * 95) * grow;
    const x = bx + p.jx * 76 * (1 - grow * 0.12);
    const y = TBASE - p.r * h;
    const wob = Math.sin(t * 2.2 + p.ph * 5) * 3;
    ctx.fillStyle = "rgba(" + (120 + p.row * 28) + ",158,198," + (0.30 + 0.45 * p.r) + ")";
    ctx.fillRect(x + wob, y, p.sz * 1.7, p.sz * 1.7);
  });
  ctx.globalCompositeOperation = "source-over";
  text("企業每天都在面對的四件事", 150, 140, { size: 40, weight: 600 });
  text("THE PAIN", 150, 184, { size: 20, color: C.dim, font: F.mono, space: 2 });
  PAINS.forEach((p, i) => {
    const e = eOut((t - 0.6 - i * 1.5) / 0.7);
    if (e <= 0) return;
    painIcon(i, TOWERX[i] - 110, 200, 220, 150, t - 0.6 - i * 1.5, a * e);
    ctx.save(); ctx.globalAlpha = a * e;
    text(p.n, TOWERX[i] - 110, 385, { size: 17, color: C.dim, font: F.mono, space: 1 });
    text(p.t, TOWERX[i] - 110, 900, { size: 24, weight: 600 });
    text(p.d, TOWERX[i] - 110, 932, { size: 17, color: C.mute });
    ctx.restore();
  });
  ctx.restore();
}

/* --- 14.5–23.5s：塔被削平，粒子流進清單，每列一張示意圖 --- */
function sceneAnswer(t) {
  const a = ss(-0.45, 0.05, t) * (1 - ss(8.4, 9.0, t));
  if (a <= 0) return;
  ctx.save(); ctx.globalAlpha = a;
  const col = eOut(clamp((t - 0.3) / 2.4, 0, 1));
  ctx.globalCompositeOperation = "lighter";
  PT.forEach(p => {
    const bx = TOWERX[p.row];
    const h = 150 + p.row * 95;
    const tx = 470 + p.r * 150;
    const ty = 330 + p.row * 150;
    const x = lerp(bx + p.jx * 76, tx, col);
    const y = lerp(TBASE - p.r * h, ty, p.r * col);
    ctx.fillStyle = "rgba(241,178,92," + (0.14 + 0.38 * col) + ")";
    ctx.fillRect(x, y, p.sz * 1.5, p.sz * 1.5);
  });
  ctx.globalCompositeOperation = "source-over";
  text("我們的專題，實際解決什麼問題", 150, 140, { size: 40, weight: 600 });
  text("PAIN → ANSWER", 150, 184, { size: 20, color: C.dim, font: F.mono, space: 2 });
  ANSWERS.forEach((v, i) => {
    const e = eOut((t - 0.9 - i * 1.8) / 0.75);
    if (e <= 0) return;
    const y = 330 + i * 150;
    ansIcon(i, 660, y - 58, 300, 112, t - 0.9 - i * 1.8, a * e);
    ctx.save(); ctx.globalAlpha = a * e;
    text(v.p, 1010, y - 14, { size: 20, color: C.dim });
    text("→", 1010, y + 26, { size: 22, color: C.hi });
    text(v.a, 1056, y + 26, { size: 32, weight: 600 });
    text(v.e, 1700, y + 26, { size: 24, color: C.hi, font: F.mono, align: "right" });
    ctx.strokeStyle = C.line; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(660, y + 62); ctx.lineTo(1700, y + 62); ctx.stroke();
    ctx.restore();
  });
  ctx.restore();
}
/* S2：6.5–18s 流水線五步 */
const STEPS = [
  { n: '01', t: '定時抓取', s: 'iThome・TWCERT/CC・NVD', at: 6.8 },
  { n: '02', t: '規則分類', s: '四類，可稽核', at: 9.0 },
  { n: '03', t: '重複偵測', s: 'URL・CVE・標題', at: 11.2 },
  { n: '04', t: '情資對接', s: 'FIRST EPSS・CISA KEV', at: 13.4 },
  { n: '05', t: '風險評分', s: 'P1–P3 + SLA', at: 15.6 }
];

/* ---- 後段氛圍：緩慢上升的微光點 + 巡迴掃描光帶（避免大片死黑） ---- */
const AMB = (() => {
  const r = rng(8081); const o = [];
  for (let i = 0; i < 110; i++) o.push({ x: r() * W, y: r() * H, s: 0.5 + r() * 1.3, v: 5 + r() * 16, a: 0.05 + r() * 0.10 });
  return o;
})();

function ambient(t) {
  const e = ss(23.0, 24.4, t);
  if (e <= 0) return;
  ctx.save();
  ctx.globalAlpha = e;
  AMB.forEach(p => {
    let y = (p.y - t * p.v) % H;
    if (y < 0) y += H;
    ctx.fillStyle = 'rgba(93,127,163,' + p.a.toFixed(3) + ')';
    ctx.fillRect(p.x, y, p.s, p.s);
  });
  const sy = ((t * 44) % (H + 260)) - 130;
  const g = ctx.createLinearGradient(0, sy - 100, 0, sy + 100);
  g.addColorStop(0, 'rgba(241,178,92,0)');
  g.addColorStop(0.5, 'rgba(241,178,92,.038)');
  g.addColorStop(1, 'rgba(241,178,92,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, sy - 100, W, 200);
  ctx.restore();
}

/* 步驟小圖示 */
function stepIcon(i, cx, cy, col, al) {
  ctx.save(); ctx.globalAlpha *= al; ctx.strokeStyle = col; ctx.fillStyle = col; ctx.lineWidth = 1.7;
  if (i === 0) {
    ctx.beginPath(); ctx.moveTo(cx, cy - 11); ctx.lineTo(cx, cy + 1); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(cx - 6, cy - 5); ctx.lineTo(cx, cy + 2); ctx.lineTo(cx + 6, cy - 5); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(cx - 11, cy + 9); ctx.lineTo(cx + 11, cy + 9); ctx.stroke();
  } else if (i === 1) {
    ctx.fillRect(cx - 11, cy - 9, 22, 4); ctx.fillRect(cx - 11, cy - 2, 15, 4); ctx.fillRect(cx - 11, cy + 5, 9, 4);
  } else if (i === 2) {
    ctx.strokeRect(cx - 12, cy - 10, 9, 20); ctx.strokeRect(cx + 3, cy - 10, 9, 20);
  } else if (i === 3) {
    ctx.beginPath(); ctx.arc(cx - 7, cy, 6, 0, TAU); ctx.stroke();
    ctx.beginPath(); ctx.arc(cx + 7, cy, 6, 0, TAU); ctx.stroke();
  } else {
    ctx.beginPath(); ctx.arc(cx, cy + 5, 12, Math.PI, 0); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(cx, cy + 5); ctx.lineTo(cx + 8, cy - 4); ctx.stroke();
  }
  ctx.restore();
}

function scene2(t) {
  const a = ss(6.2, 6.8, t) * (1 - ss(17.7, 18.5, t));
  if (a <= 0) return;
  ctx.save();
  ctx.globalAlpha = a;

  text('它到底怎麼運作', 160, 300, { size: 40, color: C.ink, weight: 600 });
  text('HOW IT WORKS · 五步流水線', 160, 344, { size: 21, color: C.dim, font: F.mono, space: 2 });

  const bw = 296, gap = 46, total = STEPS.length * bw + (STEPS.length - 1) * gap;
  const x0 = (W - total) / 2, y0 = 520, bh = 200;

  // 五個空框先全部出現，畫面不會只有一兩個盒子
  STEPS.forEach((st, i) => {
    const x = x0 + i * (bw + gap);
    const ge = eOut(clamp((t - 6.3) / 0.7, 0, 1));
    ctx.save();
    ctx.globalAlpha = a * 0.22 * ge;
    ctx.strokeStyle = i === 4 ? C.hi : C.line;
    ctx.lineWidth = 1;
    ctx.setLineDash([7, 7]);
    ctx.beginPath(); ctx.roundRect(x, y0, bw, bh, 10); ctx.stroke();
    ctx.restore();
  });

  STEPS.forEach((st, i) => {
    const e = eOut((t - st.at) / .8);
    if (e <= 0) return;
    const x = x0 + i * (bw + gap);
    const y = y0 + (1 - e) * 26;
    ctx.save();
    ctx.globalAlpha = a * e;

    ctx.fillStyle = C.panel;
    ctx.strokeStyle = i === 4 ? C.hi : C.line;
    ctx.lineWidth = i === 4 ? 2 : 1.4;
    ctx.beginPath();
    ctx.roundRect(x, y, bw, bh, 10);
    ctx.fill(); ctx.stroke();

    stepIcon(i, x + bw - 42, y + 44, i === 4 ? C.hi : C.mute, a * e);
    text(st.n, x + 28, y + 52, { size: 20, color: i === 4 ? C.hi : C.dim, font: F.mono, weight: 600, space: 1 });
    text(st.t, x + 28, y + 118, { size: 38, color: C.ink, weight: 600 });
    text(st.s, x + 28, y + 164, { size: 21, color: C.mute });
    ctx.restore();

    if (i < STEPS.length - 1) {
      const ea = eOut((t - st.at - .45) / .6);
      if (ea > 0) {
        const ax = x + bw + 6, ay = y + bh / 2;
        ctx.save();
        ctx.globalAlpha = a * ea;
        ctx.strokeStyle = C.dim; ctx.lineWidth = 1.6;
        ctx.beginPath(); ctx.moveTo(ax, ay); ctx.lineTo(ax + gap - 20, ay); ctx.stroke();
        ctx.beginPath();
        ctx.moveTo(ax + gap - 20, ay);
        ctx.lineTo(ax + gap - 28, ay - 5);
        ctx.moveTo(ax + gap - 20, ay);
        ctx.lineTo(ax + gap - 28, ay + 5);
        ctx.stroke();
        // 沿箭頭流動的資料點
        for (let k = 0; k < 3; k++) {
          const p = (t * 0.5 + k / 3) % 1;
          ctx.globalAlpha = a * ea * (0.2 + 0.7 * Math.sin(Math.PI * p));
          ctx.fillStyle = C.hi;
          ctx.beginPath(); ctx.arc(ax + 3 + p * (gap - 30), ay, 2.2, 0, TAU); ctx.fill();
        }
        ctx.restore();
      }
    }
  });
  ctx.restore();
}

/* S3a：18–27s 四類分佈 */
function scene3a(t) {
  const a = ss(17.9, 18.5, t) * (1 - ss(23.8, 24.4, t));
  if (a <= 0) return;
  ctx.save();
  ctx.globalAlpha = a;

  const cats = [
    { k: 'MALWARE',  n: '惡意威脅\n與主動攻擊', v: DATA.meta_category.MALWARE },
    { k: 'RESEARCH', n: '前瞻研究\n與平台治理', v: DATA.meta_category.RESEARCH },
    { k: 'VULN',     n: '系統漏洞\n與修補對策', v: DATA.meta_category.VULN },
    { k: 'OTHER',    n: '產業與\n產品動態', v: DATA.meta_category.OTHER }
  ];
  const max = 400, l = 300, r = 1620, top = 330, bot = 800;
  const bh2 = (bot - top) / max;

  text('四類規則分類', 300, 250, { size: 38, color: C.ink, weight: 600 });
  text('783 個去重事件 · 每筆都能說明為什麼', 300, 294, { size: 22, color: C.mute });

  ['0', '100', '200', '300', '400'].forEach((g, i) => {
    const y = bot - i * 100 * bh2;
    ctx.save(); ctx.strokeStyle = C.grid; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(l, y); ctx.lineTo(r, y); ctx.stroke(); ctx.restore();
    text(g, l - 18, y + 7, { size: 19, color: C.dim, font: F.mono, align: 'right' });
  });

  const bw = (r - l) / cats.length;
  cats.forEach((c, i) => {
    const e = eOut((t - 18.6 - i * .32) / .9);
    const hgt = c.v * bh2 * e;
    const x = l + bw * i + bw * .24, w2 = bw * .5;
    ctx.fillStyle = i === 0 ? C.hi : C.bar;
    ctx.fillRect(x, bot - hgt, w2, hgt);
    text(String(Math.round(c.v * e)), x + w2 / 2, bot - hgt - 18, { size: 30, color: C.ink, font: F.mono, weight: 600, align: 'center' });
    c.n.split('\n').forEach((line, j) => {
      text(line, x + w2 / 2, bot + 44 + j * 32, { size: 24, color: C.mute, align: 'center' });
    });
    text(c.k, x + w2 / 2, bot + 128, { size: 17, color: C.dim, font: F.mono, align: 'center', space: 1 });
  });
  ctx.restore();
}

/* S3b：24–30s 35 個月時間軸 */
function scene3b(t) {
  const a = ss(24.45, 25.0, t) * (1 - ss(29.6, 30.4, t));
  if (a <= 0) return;
  ctx.save();
  ctx.globalAlpha = a;

  const mc = DATA.months.counts, n = mc.length;
  const l = 300, r = 1620, top = 520, bot = 800, max = 100;

  text('35 個月的事件密度', 300, 300, { size: 38, color: C.ink, weight: 600 });
  text(DATA.months.first + ' → ' + DATA.months.last + ' · 每月 17–20 件，最後兩個月為語料擴充', 300, 344, { size: 22, color: C.mute });

  ctx.save(); ctx.strokeStyle = C.grid; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(l, bot); ctx.lineTo(r, bot); ctx.stroke(); ctx.restore();

  const bw = (r - l) / n;
  mc.forEach((v, i) => {
    const e = eOut((t - 24.6 - i * .06) / .45);
    const hgt = (bot - top) * (v / max) * e;
    const spike = v > 50;
    ctx.fillStyle = spike ? C.hi : C.bar;
    ctx.globalAlpha = a * (spike ? 1 : .85);
    ctx.fillRect(l + bw * i + bw * .18, bot - hgt, bw * .64, hgt);
  });
  ctx.globalAlpha = a;

  const yAvg = bot - (bot - top) * 18 / max;
  ctx.save(); ctx.strokeStyle = C.line; ctx.lineWidth = 1; ctx.setLineDash([5, 7]);
  ctx.beginPath(); ctx.moveTo(l, yAvg); ctx.lineTo(r, yAvg); ctx.stroke(); ctx.restore();
  text('月均約 18 件', l + bw * (n - 3), yAvg - 10, { size: 18, color: C.dim, font: F.mono, align: 'right' });

  text(DATA.months.first, l, bot + 40, { size: 20, color: C.dim, font: F.mono });
  text(DATA.months.last, r, bot + 40, { size: 20, color: C.dim, font: F.mono, align: 'right' });

  const e2 = ss(26.6, 27.3, t);
  if (e2 > 0) {
    ctx.globalAlpha = a * e2;
    [[n - 2, mc[n - 2]], [n - 1, mc[n - 1]]].forEach(([i, v]) => {
      const x = l + bw * i + bw * .5;
      text(String(v), x, bot - (bot - top) * (v / max) - 16, { size: 24, color: C.hi, font: F.mono, weight: 600, align: 'center' });
    });
    text('語料擴充，不是攻擊暴增', r, 434, { size: 21, color: C.hi, align: 'right' });
  }
  ctx.restore();
}

/* S4：30–44s 散點名次對照（重點鏡頭） */
function scene4(t) {
  const a = ss(30.0, 30.7, t) * (1 - ss(43.4, 44.4, t));
  if (a <= 0) return;
  ctx.save();
  ctx.globalAlpha = a;

  text('同一批 CVE，兩種排法', 300, 200, { size: 40, color: C.ink, weight: 600 });
  text('273 個有 CVE 編號的條目 · 橙點 = CISA KEV 已確認遭利用（83 個）', 300, 244, { size: 22, color: C.mute });

  const px = 300, py = 330, pw = 760, ph = 540;
  const toX = v => px + (v / (SC.n - 1)) * pw;
  const toY = v => py + (v / (SC.n - 1)) * ph;

  ctx.save();
  ctx.strokeStyle = C.grid; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(px, py + ph); ctx.lineTo(px + pw, py + ph); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(px, py + ph); ctx.stroke();
  ctx.restore();

  ctx.save();
  ctx.strokeStyle = C.line; ctx.lineWidth = 1.2; ctx.setLineDash([6, 8]);
  ctx.beginPath(); ctx.moveTo(px, py + ph); ctx.lineTo(px + pw, py); ctx.stroke();
  ctx.restore();

  text('← 按 CVSS 名次 靠前', px, py + ph + 44, { size: 20, color: C.mute, font: F.mono });
  ctx.save(); ctx.translate(px - 26, py + ph); ctx.rotate(-Math.PI / 2);
  text('← 按本系統 名次 靠前', 0, 0, { size: 20, color: C.mute, font: F.mono });
  ctx.restore();
  text('對角線 = 兩種排法完全一致', px + pw, py - 14, { size: 18, color: C.dim, align: 'right' });

  SC.pts.forEach(p => {
    const e = eOut((t - 30.8 - (p.x / SC.n) * 5.6 - p.d) / .45);
    if (e <= 0) return;
    const x = toX(p.x) + p.jx, y = toY(p.y) + p.jy;
    if (p.k) {
      ctx.save();
      const g = ctx.createRadialGradient(x, y, 0, x, y, 18);
      g.addColorStop(0, 'rgba(241,178,92,.45)');
      g.addColorStop(1, 'rgba(241,178,92,0)');
      ctx.fillStyle = g; ctx.globalAlpha = a * e * .9;
      ctx.beginPath(); ctx.arc(x, y, 18, 0, Math.PI * 2); ctx.fill();
      ctx.restore();
      ctx.fillStyle = C.hi;
      ctx.globalAlpha = a * e;
      ctx.beginPath(); ctx.arc(x, y, 4.6 * e, 0, Math.PI * 2); ctx.fill();
    } else {
      ctx.fillStyle = 'rgba(143,154,165,.5)';
      ctx.globalAlpha = a * e;
      ctx.beginPath(); ctx.arc(x, y, 3.4 * e, 0, Math.PI * 2); ctx.fill();
    }
  });
  ctx.globalAlpha = a;

  const sx = 1200;
  const ea = eOut((t - 37.4) / .9);
  ctx.globalAlpha = a * ea;
  text('已遭利用的 83 個 CVE', sx, 400, { size: 24, color: C.mute });
  text(String(DATA.kev_rank.cvss_median), sx, 500, { size: 84, color: C.ink, font: F.mono, weight: 600 });
  text('→', sx + 210, 500, { size: 60, color: C.dim });
  text(String(DATA.kev_rank.eng_median), sx + 300, 500, { size: 84, color: C.hi, font: F.mono, weight: 600 });
  text('中位名次：按 CVSS  →  按本系統', sx, 548, { size: 22, color: C.mute });

  ctx.save(); ctx.strokeStyle = C.line; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(sx, 596); ctx.lineTo(sx + 480, 596); ctx.stroke(); ctx.restore();

  text('全部落在前 ' + DATA.kev_rank.eng_max + ' 名', sx, 648, { size: 26, color: C.ink });
  text('交叉驗證 AUC', sx, 700, { size: 21, color: C.mute });
  text('0.853', sx, 750, { size: 42, color: C.ink, font: F.mono, weight: 600 });
  text('vs 純 CVSS 0.561', sx + 132, 750, { size: 24, color: C.mute, font: F.mono });
  text('precision@10 = 1.00', sx, 802, { size: 24, color: C.hi, font: F.mono });
  text('（docs/evaluation.md，2026-11-16 產生）', sx, 844, { size: 18, color: C.dim });
  ctx.restore();
}

/* S5：44–53s 產出 */
function prioIcon(i, x, y, col, al) {
  ctx.save(); ctx.globalAlpha *= al; ctx.strokeStyle = col; ctx.fillStyle = col; ctx.lineWidth = 1.7;
  if (i === 0) {
    ctx.beginPath(); ctx.arc(x, y, 13, 0, TAU); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x, y - 8); ctx.moveTo(x, y); ctx.lineTo(x + 6, y + 3); ctx.stroke();
  } else if (i === 1) {
    ctx.strokeRect(x - 12, y - 10, 24, 22);
    ctx.beginPath(); ctx.moveTo(x - 12, y - 3); ctx.lineTo(x + 12, y - 3); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(x - 6, y - 15); ctx.lineTo(x - 6, y - 8);
    ctx.moveTo(x + 6, y - 15); ctx.lineTo(x + 6, y - 8); ctx.stroke();
  } else {
    for (let k = 0; k < 3; k++) {
      ctx.beginPath(); ctx.arc(x - 9, y - 7 + k * 8, 1.9, 0, TAU); ctx.fill();
      ctx.fillRect(x - 3, y - 9 + k * 8, 15, 3);
    }
  }
  ctx.restore();
}

function scene5(t) {
  const a = ss(43.9, 44.6, t) * (1 - ss(52.4, 53.2, t));
  if (a <= 0) return;
  ctx.save();
  ctx.globalAlpha = a;

  text('輸出：可以直接排進會議的行動', 300, 300, { size: 40, color: C.ink, weight: 600 });
  text('PRIORITY · SLA · PATCH LIST', 300, 344, { size: 21, color: C.dim, font: F.mono, space: 2 });

  const rows = [
    { p: 'P1', c: DATA.priority_all.P1, sla: '24 小時', hi: true },
    { p: 'P2', c: DATA.priority_all.P2, sla: '7 天', hi: false },
    { p: 'P3', c: DATA.priority_all.P3, sla: '30 天', hi: false }
  ];
  const barX = 430, maxW = 540, iconX = 1150, slaX = 1700;

  rows.forEach((row, i) => {
    const e = eOut((t - 44.2 - i * .55) / .9);
    if (e <= 0) return;
    const y = 470 + i * 150;
    ctx.save();
    ctx.globalAlpha = a * e;

    text(row.p, 300, y, { size: 62, color: row.hi ? C.hi : C.ink, font: F.mono, weight: 600 });

    ctx.fillStyle = 'rgba(58,69,80,.40)';
    ctx.fillRect(barX, y - 34, maxW, 34);
    const w = maxW * (row.c / 500) * e;
    ctx.fillStyle = row.hi ? C.hi : C.bar;
    ctx.globalAlpha = a * e * (row.hi ? 1 : .85);
    ctx.fillRect(barX, y - 34, w, 34);

    const sp = (t * 0.55 + i * 0.33) % 1;
    ctx.globalAlpha = a * e * (0.22 * Math.sin(Math.PI * sp));
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(barX + Math.max(0, w * sp - 9), y - 34, 18, 34);

    ctx.globalAlpha = a * e;
    text(String(row.c) + ' 筆', barX + w + 18, y - 6, { size: 28, color: C.ink, font: F.mono });

    ctx.fillStyle = 'rgba(18,24,30,.55)';
    ctx.strokeStyle = row.hi ? 'rgba(241,178,92,.45)' : 'rgba(93,127,163,.30)';
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.roundRect(iconX, y - 56, 104, 70, 8); ctx.fill(); ctx.stroke();
    prioIcon(i, iconX + 52, y - 21, row.hi ? C.hi : C.mute, a * e);

    text('SLA ' + row.sla, slaX, y - 6, { size: 30, color: row.hi ? C.hi : C.mute, align: 'right' });
    ctx.restore();
  });

  const e2 = eOut((t - 46.4) / 1.0);
  ctx.globalAlpha = a * e2;
  text('每一筆都附上處置劇本與理由，交班不用重新解釋', 300, 930, { size: 24, color: C.mute });
  ctx.restore();
}

/* S6：53–60s 收尾 */
function scene6(t) {
  const a = ss(52.9, 53.8, t);
  if (a <= 0) return;
  ctx.save();
  ctx.globalAlpha = a;

  const e = eOut((t - 53.6) / 1.2);
  const br = 1 + 0.013 * Math.sin((t - 53.6) * 0.85);
  ctx.save();
  ctx.translate(W / 2, 480); ctx.scale(br, br); ctx.translate(-W / 2, -480);
  text('CTI 資安風險決策支援平台', W / 2, 480 + (1 - e) * 16, { size: 72, color: C.ink, weight: 700, align: 'center' });
  ctx.restore();
  text('把情資語料，變成 CISO 做得到的處置順序', W / 2, 566, { size: 32, color: C.hi, align: 'center', alpha: e });
  ctx.save();
  ctx.strokeStyle = C.line; ctx.lineWidth = 1.5;
  ctx.globalAlpha = a * e;
  ctx.beginPath(); ctx.moveTo(W / 2 - 240 * e, 620); ctx.lineTo(W / 2 + 240 * e, 620); ctx.stroke();
  ctx.restore();

  text('788 篇語料 · 783 個事件 · 35 個月 · 分類器 held-out 77%（baseline 44%）', W / 2, 690, { size: 22, color: C.mute, align: 'center', alpha: e });
  text('FastAPI · SQLite · Chart.js · FIRST EPSS · CISA KEV', W / 2, 732, { size: 21, color: C.dim, font: F.mono, align: 'center', alpha: e });

  ctx.restore();
}

/* ---- 字幕與頁腳 ---- */
function subtitles(t) {
  for (const [s, e, s2] of SUBS) {
    if (t < s - .2 || t > e + .2) continue;
    const a = ss(s, s + .35, t) * (1 - ss(e - .35, e, t));
    if (a <= 0) continue;
    ctx.save();
    ctx.globalAlpha = a;
    const y = 1000;
    ctx.font = '500 32px ' + F.sans;
    const tw = ctx.measureText(s2).width;
    ctx.fillStyle = 'rgba(7,8,12,.55)';
    ctx.fillRect(W / 2 - tw / 2 - 34, y - 44, tw + 68, 62);
    ctx.restore();
    text(s2, W / 2, y, { size: 32, color: '#f2f5f7', align: 'center', weight: 500, alpha: a });
  }
  const ca = ss(0.5, 1.2, t);
  text(CREDIT, W - 120, 1030, { size: 16, color: '#4a545e', align: 'right', font: F.mono, alpha: ca });
}

/* ---- 分段表：新時間窗 → 舊場景時間窗（內部時間因此等比縮放） ---- */
const SEGMENTS = [
  { f: sceneMap,    newA: 0.0,   newB: 7.0,  oldA: 0.0,   oldB: 7.0 },
  { f: scenePains,  newA: 6.55,  newB: 14.5, oldA: -0.45, oldB: 7.5 },
  { f: sceneAnswer, newA: 14.05, newB: 23.5, oldA: -0.45, oldB: 9.0 },
  { f: scene2,      newA: 23.05, newB: 32.0, oldA: 6.2,   oldB: 18.5 },
  { f: scene3a,     newA: 31.55, newB: 36.5, oldA: 17.9,  oldB: 24.4 },
  { f: scene4,      newA: 36.05, newB: 48.5, oldA: 30.0,  oldB: 44.4 },
  { f: scene5,      newA: 48.05, newB: 54.5, oldA: 43.9,  oldB: 53.2 },
  { f: scene6,      newA: 54.05, newB: 60.0, oldA: 52.9,  oldB: 60.0 }
];

/* ---- 主繪製：t 的純函數 ---- */
function draw(t) {
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1;
  ctx.fillStyle = C.bg;
  ctx.fillRect(0, 0, W, H);

  const g = ctx.createRadialGradient(W * .5, H * .42, 120, W * .5, H * .42, 1100);
  g.addColorStop(0, 'rgba(40,46,66,.28)');
  g.addColorStop(1, 'rgba(15,20,24,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);

  ambient(t);
  SEGMENTS.forEach(s => {
    const lt = s.oldA + (clamp(t, s.newA, s.newB) - s.newA) * (s.oldB - s.oldA) / (s.newB - s.newA);
    s.f(lt);
  });
  subtitles(t);

  ctx.globalAlpha = 1;
  ctx.fillStyle = 'rgba(15,20,24,.9)';
  ctx.fillRect(0, H - 6, W * clamp(t / DURATION, 0, 1), 6);
}

export default function ({ root, width, height, pixelRatio }) {
  const canvas = document.createElement('canvas');
  canvas.width = Math.round(width * pixelRatio);
  canvas.height = Math.round(height * pixelRatio);
  canvas.style.cssText = 'display:block;width:100%;height:100%';
  root.style.cssText += ';margin:0;background:#07080c;overflow:hidden';
  root.append(canvas);

  const c2d = canvas.getContext('2d');
  c2d.setTransform(pixelRatio, 0, 0, pixelRatio, 0, 0);
  __hostCtx = c2d;
  ctx = c2d;

  return {
    prepareFrame(time) {
      draw(Math.max(0, Math.min(DURATION, time)));
    },
    dispose() {
      canvas.remove();
      ctx = null;
      __hostCtx = null;
    },
  };
}
